-- First working tranche of the owner's recorded Ombuntu bindings.
-- Unavailable menu/application actions keep their chords reserved with no_op.
-- The pinned Hyprland parser and a booted-session inventory remain acceptance gates.

hl.bind("SUPER + SPACE", hl.dsp.exec_cmd("/usr/bin/walker"), { description = "Application launcher" })
hl.bind("SUPER + ALT + SPACE", hl.dsp.no_op(), { description = "Main desktop menu (reserved)" })
hl.bind("SUPER + Return", hl.dsp.exec_cmd("/usr/bin/foot"), { description = "Terminal (Foot until Kitty qualifies)" })
hl.bind("SUPER + ALT + Return", hl.dsp.no_op(), { description = "Tmux terminal (reserved)" })
hl.bind("SUPER + Escape", hl.dsp.no_op(), { description = "System menu (reserved)" })
hl.bind("SUPER + K", hl.dsp.no_op(), { description = "Keybinding help (reserved)" })
hl.bind("SUPER + SHIFT + K", hl.dsp.no_op(), { description = "Beginner keybinding help (reserved)" })
hl.bind("SUPER + CTRL + V", hl.dsp.no_op(), { description = "Clipboard menu (reserved)" })
hl.bind("Print", hl.dsp.no_op(), { description = "Screenshot menu (reserved)" })
hl.bind("ALT + Print", hl.dsp.no_op(), { description = "Screen recording menu (reserved)" })
hl.bind("SUPER + CTRL + L", hl.dsp.no_op(), { description = "Lock screen (reserved)" })
hl.bind("SUPER + SHIFT + Return", hl.dsp.no_op(), { description = "Browser (reserved)" })
hl.bind("SUPER + SHIFT + B", hl.dsp.no_op(), { description = "Browser (reserved alternate)" })
hl.bind("SUPER + SHIFT + F", hl.dsp.no_op(), { description = "File manager (reserved)" })
hl.bind("SUPER + SHIFT + N", hl.dsp.no_op(), { description = "Editor (reserved)" })

hl.bind("SUPER + W", hl.dsp.window.close(), { description = "Close window" })
hl.bind("SUPER + T", hl.dsp.window.float({ action = "toggle" }), { description = "Toggle window floating" })
hl.bind("SUPER + F", hl.dsp.window.fullscreen({ mode = "fullscreen", action = "toggle" }), { description = "Full screen" })

hl.bind("SUPER + left", hl.dsp.focus({ direction = "left" }), { description = "Focus left window" })
hl.bind("SUPER + right", hl.dsp.focus({ direction = "right" }), { description = "Focus right window" })
hl.bind("SUPER + up", hl.dsp.focus({ direction = "up" }), { description = "Focus above window" })
hl.bind("SUPER + down", hl.dsp.focus({ direction = "down" }), { description = "Focus below window" })
hl.bind("SUPER + SHIFT + left", hl.dsp.window.swap({ direction = "left" }), { description = "Swap window left" })
hl.bind("SUPER + SHIFT + right", hl.dsp.window.swap({ direction = "right" }), { description = "Swap window right" })
hl.bind("SUPER + SHIFT + up", hl.dsp.window.swap({ direction = "up" }), { description = "Swap window up" })
hl.bind("SUPER + SHIFT + down", hl.dsp.window.swap({ direction = "down" }), { description = "Swap window down" })

hl.bind("SUPER + code:10", hl.dsp.focus({ workspace = 1 }), { description = "Switch to workspace 1" })
hl.bind("SUPER + code:11", hl.dsp.focus({ workspace = 2 }), { description = "Switch to workspace 2" })
hl.bind("SUPER + code:12", hl.dsp.focus({ workspace = 3 }), { description = "Switch to workspace 3" })
hl.bind("SUPER + code:13", hl.dsp.focus({ workspace = 4 }), { description = "Switch to workspace 4" })
hl.bind("SUPER + code:14", hl.dsp.focus({ workspace = 5 }), { description = "Switch to workspace 5" })
hl.bind("SUPER + code:15", hl.dsp.focus({ workspace = 6 }), { description = "Switch to workspace 6" })
hl.bind("SUPER + code:16", hl.dsp.focus({ workspace = 7 }), { description = "Switch to workspace 7" })
hl.bind("SUPER + code:17", hl.dsp.focus({ workspace = 8 }), { description = "Switch to workspace 8" })
hl.bind("SUPER + code:18", hl.dsp.focus({ workspace = 9 }), { description = "Switch to workspace 9" })
hl.bind("SUPER + code:19", hl.dsp.focus({ workspace = 10 }), { description = "Switch to workspace 10" })

hl.bind("SUPER + SHIFT + code:10", hl.dsp.window.move({ workspace = 1 }), { description = "Move window to workspace 1" })
hl.bind("SUPER + SHIFT + code:11", hl.dsp.window.move({ workspace = 2 }), { description = "Move window to workspace 2" })
hl.bind("SUPER + SHIFT + code:12", hl.dsp.window.move({ workspace = 3 }), { description = "Move window to workspace 3" })
hl.bind("SUPER + SHIFT + code:13", hl.dsp.window.move({ workspace = 4 }), { description = "Move window to workspace 4" })
hl.bind("SUPER + SHIFT + code:14", hl.dsp.window.move({ workspace = 5 }), { description = "Move window to workspace 5" })
hl.bind("SUPER + SHIFT + code:15", hl.dsp.window.move({ workspace = 6 }), { description = "Move window to workspace 6" })
hl.bind("SUPER + SHIFT + code:16", hl.dsp.window.move({ workspace = 7 }), { description = "Move window to workspace 7" })
hl.bind("SUPER + SHIFT + code:17", hl.dsp.window.move({ workspace = 8 }), { description = "Move window to workspace 8" })
hl.bind("SUPER + SHIFT + code:18", hl.dsp.window.move({ workspace = 9 }), { description = "Move window to workspace 9" })
hl.bind("SUPER + SHIFT + code:19", hl.dsp.window.move({ workspace = 10 }), { description = "Move window to workspace 10" })

hl.bind("SUPER + SHIFT + ALT + code:10", hl.dsp.window.move({ workspace = 1, follow = false }), { description = "Move window silently to workspace 1" })
hl.bind("SUPER + SHIFT + ALT + code:11", hl.dsp.window.move({ workspace = 2, follow = false }), { description = "Move window silently to workspace 2" })
hl.bind("SUPER + SHIFT + ALT + code:12", hl.dsp.window.move({ workspace = 3, follow = false }), { description = "Move window silently to workspace 3" })
hl.bind("SUPER + SHIFT + ALT + code:13", hl.dsp.window.move({ workspace = 4, follow = false }), { description = "Move window silently to workspace 4" })
hl.bind("SUPER + SHIFT + ALT + code:14", hl.dsp.window.move({ workspace = 5, follow = false }), { description = "Move window silently to workspace 5" })
hl.bind("SUPER + SHIFT + ALT + code:15", hl.dsp.window.move({ workspace = 6, follow = false }), { description = "Move window silently to workspace 6" })
hl.bind("SUPER + SHIFT + ALT + code:16", hl.dsp.window.move({ workspace = 7, follow = false }), { description = "Move window silently to workspace 7" })
hl.bind("SUPER + SHIFT + ALT + code:17", hl.dsp.window.move({ workspace = 8, follow = false }), { description = "Move window silently to workspace 8" })
hl.bind("SUPER + SHIFT + ALT + code:18", hl.dsp.window.move({ workspace = 9, follow = false }), { description = "Move window silently to workspace 9" })
hl.bind("SUPER + SHIFT + ALT + code:19", hl.dsp.window.move({ workspace = 10, follow = false }), { description = "Move window silently to workspace 10" })

hl.bind("SUPER + TAB", hl.dsp.focus({ workspace = "e+1" }), { description = "Next workspace" })
hl.bind("SUPER + SHIFT + TAB", hl.dsp.focus({ workspace = "e-1" }), { description = "Previous workspace" })
hl.bind("SUPER + CTRL + TAB", hl.dsp.focus({ workspace = "previous" }), { description = "Former workspace" })

hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("/usr/bin/wpctl set-volume -l 1 @DEFAULT_AUDIO_SINK@ 5%+"), { description = "Volume up", locked = true, repeating = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("/usr/bin/wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"), { description = "Volume down", locked = true, repeating = true })
hl.bind("XF86AudioMute", hl.dsp.exec_cmd("/usr/bin/wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"), { description = "Mute", locked = true, repeating = true })
hl.bind("XF86AudioMicMute", hl.dsp.exec_cmd("/usr/bin/wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"), { description = "Mute microphone", locked = true, repeating = true })
hl.bind("XF86MonBrightnessUp", hl.dsp.exec_cmd("/usr/bin/brightnessctl -e4 -n2 set 5%+"), { description = "Brightness up", locked = true, repeating = true })
hl.bind("XF86MonBrightnessDown", hl.dsp.exec_cmd("/usr/bin/brightnessctl -e4 -n2 set 5%-"), { description = "Brightness down", locked = true, repeating = true })
hl.bind("XF86AudioNext", hl.dsp.exec_cmd("/usr/bin/playerctl next"), { description = "Next track", locked = true })
hl.bind("XF86AudioPause", hl.dsp.exec_cmd("/usr/bin/playerctl play-pause"), { description = "Pause", locked = true })
hl.bind("XF86AudioPlay", hl.dsp.exec_cmd("/usr/bin/playerctl play-pause"), { description = "Play", locked = true })
hl.bind("XF86AudioPrev", hl.dsp.exec_cmd("/usr/bin/playerctl previous"), { description = "Previous track", locked = true })
